const b = $input.first().json.body || $input.first().json || {};
const op = (b.op || 'list').toString();
if (!['list', 'get', 'set', 'add', 'delete'].includes(op)) throw new Error('unknown op');
const q = (s) => (s || '').toString().replace(/'/g, "''");
const sel = `SELECT m.channel_code, m.label, COALESCE(m.persona_system, '') AS persona_system, COALESCE((SELECT json_agg(group_id ORDER BY group_id) FROM channel_rag_groups WHERE channel_code = m.channel_code), '[]') AS group_ids, m.line_bot_id, (m.line_channel_token IS NOT NULL AND m.line_channel_token <> '') AS has_token, m.is_active FROM channel_map m`;
let sql = '';
if (op === 'list') {
  sql = `SELECT COALESCE((SELECT json_agg(row_to_json(t)) FROM (${sel} ORDER BY m.channel_code) t), '[]') AS rows`;
} else if (op === 'get') {
  const code = (b.channel || b.channel_code || '').toString();
  const bot = (b.line_bot_id || b.destination || '').toString();
  if (bot) {
    sql = `SELECT COALESCE((SELECT json_agg(row_to_json(t)) FROM (${sel} WHERE m.line_bot_id = '${q(bot)}') t), '[]') AS rows`;
  } else {
    if (!/^[a-z0-9_]{2,32}$/.test(code)) throw new Error('bad channel');
    sql = `SELECT COALESCE((SELECT json_agg(row_to_json(t)) FROM (${sel} WHERE m.channel_code = '${code}') t), '[]') AS rows`;
  }
} else if (op === 'add') {
  const code = (b.channel || b.channel_code || '').toString().toLowerCase();
  if (!/^[a-z0-9_]{2,32}$/.test(code)) throw new Error('bad channel');
  const label = q((b.label || '').toString().slice(0, 100));
  const gids = (Array.isArray(b.group_ids) ? b.group_ids : (b.rag_group_id !== undefined ? [b.rag_group_id] : [])).map(function(x){ return parseInt(x); }).filter(function(x){ return x > 0; });
  const bot = (b.line_bot_id || '').toString().trim();
  const tok = (b.line_channel_token || '').toString().slice(0, 255);
  const act = (b.is_active !== undefined && parseInt(b.is_active) === 0) ? 0 : 1;
  const per = q((b.persona_system || b.persona || '').toString().slice(0, 4000));
  sql = `SELECT * FROM cd_channel_add('${code}', '${label}', ARRAY[${gids.join(',')}]::int[], ${bot ? `'${q(bot.slice(0, 64))}'` : 'NULL'}, '${q(tok)}', ${act}, '${per}')`;
} else if (op === 'delete') {
  const code = (b.channel || b.channel_code || '').toString();
  if (!/^[a-z0-9_]{2,32}$/.test(code)) throw new Error('bad channel');
  sql = `SELECT * FROM cd_channel_del('${code}')`;
} else if (op === 'set') {
  const code = (b.channel || b.channel_code || '').toString();
  if (!/^[a-z0-9_]{2,32}$/.test(code)) throw new Error('bad channel');
  const has = function(k){ return b[k] !== undefined; };
  const label = has('label') ? `'${q(b.label.toString().slice(0, 100))}'` : 'NULL';
  const gids = has('group_ids') ? (Array.isArray(b.group_ids) ? b.group_ids : [b.group_ids]).map(function(x){ return parseInt(x); }).filter(function(x){ return x > 0; })
    : (has('rag_group_id') && b.rag_group_id !== null && b.rag_group_id !== '' ? [parseInt(b.rag_group_id)].filter(function(x){ return x > 0; }) : null);
  const gpart = (gids === null) ? 'NULL' : `ARRAY[${gids.join(',')}]::int[]`;
  const bot = !has('line_bot_id') ? 'NULL' : ((b.line_bot_id || '').toString().trim() ? `'${q(b.line_bot_id.toString().trim().slice(0, 64))}'` : `''`);
  const tok = !has('line_channel_token') ? 'NULL' : `'${q(b.line_channel_token.toString().slice(0, 255))}'`;
  const act = !has('is_active') ? 'NULL' : ((parseInt(b.is_active) === 0) ? 0 : 1);
  const per = !has('persona_system') && !has('persona') ? 'NULL' : `'${q(((b.persona_system !== undefined ? b.persona_system : b.persona) || '').toString().slice(0, 4000))}'`;
  sql = `SELECT * FROM cd_channel_set('${code}', ${label}, ${gpart}, ${bot}, ${tok}, ${act}, ${per})`;
}
return [{ json: { op: op, sql: sql } }];

const op = $('Build SQL').first().json.op || '';
const r0 = $input.first().json;
if (op === 'set') {
  const outs = $input.all().map(function(r){ return r.json; });
  let n = parseInt(r0.updated) || 0;
  for (const o of outs) { if (o && o.updated !== undefined && o.updated !== null) { n = parseInt(o.updated) || 0; break; } }
  if (!n) return [{ json: { ok: false, error: 'ไม่พบช่องทางนี้' } }];
  return [{ json: { ok: true, updated: n } }];
}
let rows = r0.rows || [];
if (typeof rows === 'string') { try { rows = JSON.parse(rows); } catch(e) { rows = []; } }
if (op === 'add') {
  const outs = $input.all().map(function(r){ return r.json; });
  let added = null, aerr = '';
  for (const o of outs) { if (o && o.added) { added = o.added; break; } if (o && o.err) { aerr = o.err; } }
  if (!added) return [{ json: { ok: false, error: aerr || 'เพิ่มไม่สำเร็จ' } }];
  return [{ json: { ok: true, channel_code: added } }];
}
if (op === 'delete') {
  const outs = $input.all().map(function(r){ return r.json; });
  let nd = 0;
  for (const o of outs) { if (o && o.deleted !== undefined && o.deleted !== null) { nd = parseInt(o.deleted) || 0; break; } }
  if (!nd) return [{ json: { ok: false, error: 'ไม่พบช่องทางนี้' } }];
  return [{ json: { ok: true, deleted: nd } }];
}
if (op === 'get') {
  const r = rows[0] || null;
  if (!r) return [{ json: { ok: false, error: 'ไม่พบช่องทางนี้' } }];
  r.is_active = parseInt(r.is_active) || 0;
  r.rag_group_id = r.rag_group_id === null ? null : parseInt(r.rag_group_id);
  return [{ json: { ok: true, channel: r } }];
}
return [{ json: { ok: true, channels: rows.map(r => ({ ...r, is_active: parseInt(r.is_active) || 0 })) } }];
